1	package server
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"net/http"
8		"net/http/httptest"
9		"strings"
10		"testing"
11	)
12	
13	// recordingProvider is the injected Provider used by the apply tests. It
14	// records every request it receives in order and can be told to fail on a
15	// given change index.
16	type recordingProvider struct {
17		calls   []ChangeRequest
18		failAt  int
19		failErr error
20		ctx     context.Context
21	}
22	
23	func (p *recordingProvider) Apply(req ChangeRequest) error {
24		if p.ctx != nil && req.Context != p.ctx {
25			return errors.New("request did not carry the inbound context")
26		}
27		idx := len(p.calls)
28		p.calls = append(p.calls, req)
29		if p.failErr != nil && idx == p.failAt {
30			return p.failErr
31		}
32		return nil
33	}
34	
35	type applyResult struct {
36		status  int
37		raw     map[string]any
38		Valid   bool              `json:"valid"`
39		Errors  []validationError `json:"errors"`
40		Applied *[]planChange     `json:"applied"`
41		Summary *planSummary      `json:"summary"`
42		State   *struct {
43			Resources []stateResource `json:"resources"`
44		} `json:"state"`
45	}
46	
47	func doApply(t *testing.T, handler http.Handler, body string, ctx context.Context) applyResult {
48		t.Helper()
49		req := httptest.NewRequest(http.MethodPost, "/v1/apply", strings.NewReader(body))
50		if ctx != nil {
51			req = req.WithContext(ctx)
52		}
53		rec := httptest.NewRecorder()
54		handler.ServeHTTP(rec, req)
55		if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
56			t.Fatalf("Content-Type = %q, want application/json", ct)
57		}
58		var res applyResult
59		res.status = rec.Code
60		if err := json.Unmarshal(rec.Body.Bytes(), &res.raw); err != nil {
61			t.Fatalf("response is not JSON: %v (body %q)", err, rec.Body.String())
62		}
63		if err := json.Unmarshal(rec.Body.Bytes(), &res); err != nil {
64			t.Fatalf("decode typed response: %v (body %q)", err, rec.Body.String())
65		}
66		return res
67	}
68	
69	func providerCallsSummary(calls []ChangeRequest) string {
70		parts := make([]string, 0, len(calls))
71		for _, c := range calls {
72			parts = append(parts, c.Action+":"+c.Address)
73		}
74		return strings.Join(parts, "|")
75	}
76	
77	func stateAddresses(res applyResult) string {
78		if res.State == nil {
79			return "<no state>"
80		}
81		parts := make([]string, 0, len(res.State.Resources))
82		for _, r := range res.State.Resources {
83			parts = append(parts, r.Address)
84		}
85		return strings.Join(parts, "|")
86	}
