150	func TestApplySuccessExecutesInOrderAndBuildsState(t *testing.T) {
151		// Plan: delete old (reverse state order), then create new, then update
152		// keep; c is an untouched noop.
153		body := planBody(
154			`[`+resEntry("c", `[]`)+`,`+resEntry("keep", `["new"]`)+`,`+resEntry("new", `[]`)+`]`,
155			`[`+
156				stateEntry("old", "t", `{}`, `["keep"]`)+`,`+
157				stateEntry("keep", "t", `{"v": 1}`, ``)+`,`+
158				stateEntry("c", "t", `{}`, ``)+`]`)
159		provider := &recordingProvider{}
