```go
var errStateFileInvalid = errors.New("state file content is invalid")

func readStateFile(path string) (revision int64, resources []planResource, order []string, err error) {
    data, err := os.ReadFile(path)
    if err != nil {
        if errors.Is(err, os.ErrNotExist) {
            return 0, nil, nil, nil
        }
        return 0, nil, nil, err
    }
    dec := json.NewDecoder(bytes.NewReader(data))
    dec.UseNumber()
    var doc any
    if err := dec.Decode(&doc); err != nil {
        return 0, nil, nil, errStateFileInvalid
    }
    var trailing any
    if err := dec.Decode(&trailing); err != io.EOF {
        return 0, nil, nil, errStateFileInvalid
    }
    root, ok := doc.(map[string]any)
    if !ok {
        return 0, nil, nil, errStateFileInvalid
    }
    revRaw, ok := root["revision"]
    if !ok {
        return 0, nil, nil, errStateFileInvalid
    }
    revNum, ok := revRaw.(json.Number)
    if !ok {
        return 0, nil, nil, errStateFileInvalid
    }
    revision, ok = parseRevision(revNum)
    if !ok {
        return 0, nil, nil, errStateFileInvalid
    }
    stateRaw, ok := root["state"]
    if !ok {
        return 0, nil, nil, errStateFileInvalid
    }
    resources, order, errs := checkPriorState(stateRaw)
    if len(errs) != 0 {
        return 0, nil, nil, errStateFileInvalid
    }
    return revision, resources, order, nil
}
