// parseRevision interprets a JSON number as a non-negative integer revision.
func parseRevision(n json.Number) (int64, bool) {
    if !isJSONInteger(n) {
        return 0, false
    }
    r, ok := new(big.Rat).SetString(n.String())
    if !ok || !r.IsInt() {
        return 0, false
    }
    num := r.Num()
    if num.Sign() < 0 || !num.IsInt64() {
        return 0, false
    }
    return num.Int64(), true
}
```

